        const describedBy = [
          field.helperText ? `${field.id}-help` : "",
          `${field.id}-error`
        ]
          .filter(Boolean)
          .join(" ");
        const requiredMarker = field.required
          ? ' <span class="required-marker" aria-hidden="true">*</span>'
          : " <span class=\"optional-label\">(optional)</span>";
        const requiredAttribute = field.required ? " required" : "";
        const helperText = field.helperText
          ? `<p class="helper-text" id="${field.id}-help">${field.helperText}</p>`
          : "";

        return `
          <div class="form-field">
            <label for="${field.id}">${field.label}${requiredMarker}</label>
            <input
              id="${field.id}"
              name="${field.name}"
              type="${field.type}"
              autocomplete="${field.autocomplete}"
              aria-describedby="${describedBy}"
              aria-invalid="false"${requiredAttribute}
            >
            ${helperText}
            <p class="error-message" id="${field.id}-error"></p>
          </div>
        `;
