         margin: 0 auto;
         padding: 3rem 1rem;
       }

       .hero {
         display: grid;
         grid-template-columns: minmax(0, 1fr) minmax(20rem, 28rem);
         gap: 3rem;
         align-items: center;
       }

       .eyebrow {
         display: inline-flex;
         margin: 0 0 1rem;
         padding: 0.35rem 0.75rem;
