         border-radius: 1.5rem;
         box-shadow: 0 1.5rem 4rem rgba(22, 32, 51, 0.14);
         backdrop-filter: blur(16px);
       }

       .form-heading {
         margin: 0 0 0.5rem;
         font-size: 1.5rem;
         letter-spacing: -0.03em;
       }

       .form-note {
         margin: 0 0 1.5rem;
         color: var(--muted);
