           outline-offset: 3px;
           box-shadow: none;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>

     <main id="main-content" class="page-shell">
       <section class="hero" aria-labelledby="page-title">
         <div>
           <p class="eyebrow">Support request</p>
           <h1 id="page-title">Contact our support team</h1>
           <p class="intro">
             Tell us how to reach you and we will route your request to the right specialist.
           </p>
         </div>

         <div class="support-card" id="app">
           <h2 class="form-heading">How can we contact you?</h2>
           <p class="form-note">We usually respond within one business day.</p>
           <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> indicates a required field.</p>
           <form id="support-form" novalidate>
             <div class="form-field">
               <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
               <input
                 id="full-name"
                 name="fullName"
                 type="text"
                 autocomplete="name"
                 aria-describedby="full-name-error"
                 aria-invalid="false"
                 required
               >
               <p class="error-message" id="full-name-error"></p>
             </div>

             <div class="form-field">
               <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
               <input
                 id="email"
                 name="email"
                 type="email"
                 autocomplete="email"
                 aria-describedby="email-error"
                 aria-invalid="false"
                 required
               >
               <p class="error-message" id="email-error"></p>
             </div>

             <div class="form-field">
               <label for="phone">Phone number <span class="optional-label">(optional)</span></label>
               <input
                 id="phone"
                 name="phone"
                 type="tel"
                 autocomplete="tel"
                 aria-describedby="phone-help phone-error"
                 aria-invalid="false"
               >
               <p class="helper-text" id="phone-help">Use 10 digits, or include a country code such as +1 555 123 4567.</p>
               <p class="error-message" id="phone-error"></p>
             </div>

             <button class="submit-button" type="submit">Send request</button>
           </form>
           <p class="status-message" id="form-status" aria-live="polite"></p>
         </div>
       </section>
     </main>

     <script>
       const fieldConfig = [
         {
           id: "full-name",
           name: "fullName",
           label: "Full name",
           type: "text",
           autocomplete: "name",
           required: true,
           messages: {
             required: "Error: Enter your full name."
           }
         },
         {
           id: "email",
           name: "email",
           label: "Email address",
           type: "email",
           autocomplete: "email",
           required: true,
           messages: {
             required: "Error: Enter your email address.",
             invalid: "Error: Enter a valid email address, like name@example.com."
           },
           validate(value) {
             return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
           }
         },
         {
           id: "phone",
           name: "phone",
           label: "Phone number",
           type: "tel",
           autocomplete: "tel",
           required: false,
           helperText: "Use 10 digits, or include a country code such as +1 555 123 4567.",
           messages: {
             invalid: "Error: Enter a phone number using digits, spaces, dashes, parentheses, or a leading plus sign."
           },
           validate(value) {
             return /^[+]?[\d\s().-]{7,20}$/.test(value);
           }
         }
       ];

       function getError(field, value) {
         const trimmedValue = value.trim();

         if (field.required && trimmedValue.length === 0) {
           return field.messages.required;
         }

         if (trimmedValue.length > 0 && field.validate && !field.validate(trimmedValue)) {
           return field.messages.invalid;
         }

         return "";
       }

       function setFieldError(input, errorText) {
         const errorElement = document.getElementById(`${input.id}-error`);
         input.setAttribute("aria-invalid", errorText ? "true" : "false");
         errorElement.textContent = errorText;
         errorElement.classList.toggle("is-visible", Boolean(errorText));
       }

       function validateField(field) {
         const input = document.getElementById(field.id);
         const errorText = getError(field, input.value);
         setFieldError(input, errorText);
         return !errorText;
       }

       function FormField({ field, status }) {
         const input = document.getElementById(field.id);

         input.addEventListener("blur", () => validateField(field));
         input.addEventListener("input", () => {
           status.textContent = "";
           status.className = "status-message";
           if (input.getAttribute("aria-invalid") === "true") {
             validateField(field);
           }
         });

         return {
           field,
           focus() {
             input.focus();
           },
           resetError() {
             setFieldError(input, "");
           },
           validate() {
             return validateField(field);
           }
         };
       }

       function SupportContactForm({ root }) {
         const form = root.querySelector("#support-form");
         const status = root.querySelector("#form-status");
         const fields = fieldConfig.map((field) => FormField({ field, status }));

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           const firstInvalidField = fields.find((field) => !field.validate());

           if (firstInvalidField) {
             status.textContent = "Please fix the highlighted fields before sending your request.";
             status.className = "status-message";
             firstInvalidField.focus();
             return;
           }

           form.reset();
           fields.forEach((field) => field.resetError());
           status.textContent = "Thanks. Your support request has been prepared successfully.";
           status.className = "status-message success";
         });
       }

       SupportContactForm({ root: document.getElementById("app") });
     </script>
   </body>
 </html>

